#include <ImfNamespace.h>
#include <ImfCheckFile.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

using OPENEXR_IMF_NAMESPACE::checkOpenEXRFile;

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 1; }
    FILE* f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* buf = (char*)malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    // match openexr_exrcorecheck_fuzzer: reduceMemory=true, reduceTime=true, runCoreCheck=true
    checkOpenEXRFile((const char*)buf, (size_t)sz, true, true, true);
    free(buf);
    return 0;
}
EOF
